/**
 * True when the route carries an ATOMIC_AGGREGATE attribute (RFC 4271
 * §5.1.6). Writes `1` to `*out` when present, `0` when absent. Returns
 * `LR_ERR_NULL` (-1) on a NULL handle.
 *
 * # Safety
 * `route` must be a valid handle; `out` must point to writable `uint8_t`.
 */
int32_t lr_route_atomic_aggregate(lr_route_t route, uint8_t *out);

/**
 * The route's ORIGINATOR_ID (RFC 4456 §8) — writes the 4-byte IPv4
 * address to `*out_addr` and `1` to `*out_present` when the attribute
 * is present; `0` to `*out_present` when absent.
 *
 * # Safety
 * `route` must be a valid handle; `out_addr` must point to 4 writable
 * bytes; `out_present` must point to a writable `uint8_t`.
 */
int32_t lr_route_originator_id(lr_route_t route, uint8_t *out_addr, uint8_t *out_present);

/**
 * True when the route carries a CLUSTER_LIST attribute (RFC 4456 §8).
 * Writes `1` to `*out` when present, `0` when absent.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_has_cluster_list(lr_route_t route, uint8_t *out);

/**
 * The CLUSTER_LIST length (number of Cluster-ID entries). `0` when
 * the attribute is absent.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_cluster_list_len(lr_route_t route, uintptr_t *out);

/**
 * Read one Cluster-ID at `index`. Writes the 4-byte IPv4 address to
 * `*out_addr`. Returns `LR_ERR_NULL` (-1) on a NULL handle, and
 * `LR_ERR_INVALID_HANDLE` (-2) when the index is out of range.
 *
 * # Safety
 * `route` must be a valid handle; `out_addr` must point to 4 writable
 * bytes.
 */
int32_t lr_route_cluster_list_at(lr_route_t route, uintptr_t index, uint8_t *out_addr);

/**
 * True when the route carries an OTC (Only To Customer) attribute
 * (RFC 9231 §4).
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_has_otc(lr_route_t route, uint8_t *out);

/**
 * The OTC value (RFC 9231 §4). Writes the 4-byte value to `*out` and
 * `1` to `*out_present` when present; `0` to `*out_present` when
 * absent.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_otc(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * True when the route carries an AIGP attribute (RFC 7311).
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_has_aigp(lr_route_t route, uint8_t *out);

/**
 * The AIGP value (RFC 7311). Writes the 8-byte value to `*out` and
 * `1` to `*out_present` when present; `0` to `*out_present` when
 * absent.
 *
 * # Safety
 * `out` must point to a writable `uint64_t`.
 */
int32_t lr_route_aigp(lr_route_t route, uint64_t *out, uint8_t *out_present);

/**
 * True when the route carries an AGGREGATOR attribute (RFC 4271
 * §5.1.7 / RFC 6793 §4).
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_has_aggregator(lr_route_t route, uint8_t *out);

/**
 * The AGGREGATOR AS number (RFC 4271 §5.1.7 / RFC 6793 §4). Writes the
 * 4-byte value to `*out` and `1` to `*out_present` when present; `0`
 * to `*out_present` when absent.
 *
 * # Safety
 * See [`lr_route_otc`].
 */
int32_t lr_route_aggregator_asn(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * The AGGREGATOR speaker IPv4 address (RFC 4271 §5.1.7 / RFC 6793
 * §4). Writes the 4 bytes to `*out_addr` and `1` to `*out_present`
 * when present; `0` to `*out_present` when absent.
 *
 * # Safety
 * `out_addr` must point to 4 writable bytes.
 */
int32_t lr_route_aggregator_speaker(lr_route_t route, uint8_t *out_addr, uint8_t *out_present);

/**
 * True when the route carries a PMSI_TUNNEL attribute (RFC 6514 §5).
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_has_pmsi_tunnel(lr_route_t route, uint8_t *out);

/**
 * The PMSI_TUNNEL flags (RFC 6514 §5). Writes the 1-byte value to
 * `*out_flags` and `1` to `*out_present` when present; `0` to
 * `*out_present` when absent.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_pmsi_tunnel_flags(lr_route_t route, uint8_t *out_flags, uint8_t *out_present);

/**
 * The flat AS sequence length (sets flattened in order).
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_as_sequence_len(lr_route_t route, uintptr_t *out);

/**
 * Read one AS from the flat AS sequence at `index`. Returns
 * `LR_ERR_INVALID_HANDLE` (-2) when the index is out of range.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_as_sequence_at(lr_route_t route, uintptr_t index, uint32_t *out);

/**
 * Replace the route's AS_PATH with a flat AS_SEQUENCE of the given
 * ASNs (RFC 4271 §5.1.2). The previous AS_PATH is overwritten.
 *
 * # Safety
 * `asns` must point to `count` readable `uint32_t` values.
 */
int32_t lr_route_set_as_sequence(lr_route_t route, const uint32_t *asns, uintptr_t count);

/**
 * Prepend `asn` to the route's AS_PATH (RFC 4271 §5.1.2 — the
 * standard eBGP AS_PATH prepend action). Creates an AS_PATH if absent.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_prepend_as(lr_route_t route, uint32_t asn);

/**
 * Remove `community` from the route's COMMUNITIES attribute (RFC 1997
 * §4). No-op when the route carries no COMMUNITIES or the community
 * is not present.
 *
 * # Safety
 * See [`lr_route_atomic_aggregate`].
 */
int32_t lr_route_remove_community(lr_route_t route, uint32_t asn, uint16_t value);

/**
 * True when the route carries a Babel metric attribute.
 */
int32_t lr_route_has_babel_metric(lr_route_t route, uint8_t *out);

/**
 * The Babel primary metric (RFC 8966 §3.2 + §3.4.3).
 */
int32_t lr_route_babel_metric(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * True when the route carries a Babel sequence number attribute.
 */
int32_t lr_route_has_babel_seqno(lr_route_t route, uint8_t *out);

/**
 * The Babel sequence number (RFC 8966 §3.2 + §4.6.9).
 */
int32_t lr_route_babel_seqno(lr_route_t route, uint16_t *out, uint8_t *out_present);

/**
 * True when the route carries a Babel router-id attribute.
 */
int32_t lr_route_has_babel_router_id(lr_route_t route, uint8_t *out);

/**
 * The Babel router-id (RFC 8966 §3.2 + §4.6.9) — 8 bytes, written
 * through `*out_router_id` (which must point to 8 writable bytes).
 */
int32_t lr_route_babel_router_id(lr_route_t route, uint8_t *out_router_id, uint8_t *out_present);

/**
 * True when the route carries an OSPF metric1 attribute.
 */
int32_t lr_route_has_ospf_metric1(lr_route_t route, uint8_t *out);

/**
 * The OSPF primary metric (RFC 2328 §16 / RFC 5340 §4.1).
 */
int32_t lr_route_ospf_metric1(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * True when the route carries an OSPF metric2 attribute.
 */
int32_t lr_route_has_ospf_metric2(lr_route_t route, uint8_t *out);

/**
 * The OSPF type-2 external metric (RFC 2328 §16.4 / RFC 5340 §4.8.5).
 */
int32_t lr_route_ospf_metric2(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * True when the route carries an OSPF tag attribute.
 */
int32_t lr_route_has_ospf_tag(lr_route_t route, uint8_t *out);

/**
 * The OSPF external route tag (RFC 2328 §A.4.5 bullet h / RFC 3101
 * §2.3 / RFC 5340 §A.4.7 T bit / RFC 8362 §3.6 External-Prefix
 * sub-TLV 3).
 */
int32_t lr_route_ospf_tag(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * True when the route carries an OSPF router-id attribute.
 */
int32_t lr_route_has_ospf_router_id(lr_route_t route, uint8_t *out);

/**
 * The OSPF advertising router (RFC 2328 §A.4 / RFC 5340 §A.4).
 */
int32_t lr_route_ospf_router_id(lr_route_t route, uint32_t *out, uint8_t *out_present);

/**
 * The LRXP store kind tag (0 = absent, 1 = verified, 2 =
 * partial-raw). Writes `0` to `*out` when the route carries no
 * LRXP attribute (the fallback case).
 */
int32_t lr_route_lrxp_store_kind(lr_route_t route, uint8_t *out, uint8_t *out_present);

/**
 * True when the route carries a verified LRXP record set.
 */
int32_t lr_route_lrxp_verified(lr_route_t route, uint8_t *out);

/**
 * True when the route carries partial-transit LRXP forwarding
 * material.
 */
int32_t lr_route_lrxp_partial_transit(lr_route_t route, uint8_t *out);

/**
 * The sender's best-path rank for this path among its alternates
 * (design §5.1: 1 = the path the sender itself uses). `0` when
 * the route carries no verified hint record.
 */
int32_t lr_route_lrxp_hint_rank(lr_route_t route, uint8_t *out);

/**
 * The sender's route-flap figure of merit for the prefix (design
 * §5.1: 0 when damping is off). `0` when the route carries no
 * verified hint record.
 */
int32_t lr_route_lrxp_hint_damp_fom(lr_route_t route, uint16_t *out);

/**
 * The sender's IGP cost from its decision point to this path's
 * next hop (design §5.1). `0` when the route carries no verified
 * hint record.
 */
int32_t lr_route_lrxp_hint_igp_cost(lr_route_t route, uint32_t *out);

/**
 * The sender's RFC 9234 role claim for this session (design
 * §5.2: 0 = provider, 1 = customer, 2 = RS, 3 = RS-client, 4 =
 * peer, 255 = unspecified; advisory — the receiver cross-checks
 * against its own configured role). `255` (unspecified) when the
 * route carries no verified policy record.
 */
int32_t lr_route_lrxp_policy_role(lr_route_t route, uint8_t *out);

/**
 * The origin AS the attestation authorises for this announcement
 * set (design §5.3). `0` when the route carries no verified origin
 * record.
 */
int32_t lr_route_lrxp_origin_as(lr_route_t route, uint32_t *out);

/**
 * The maximum prefix length the origin authorises for this
 * announcement set (design §5.3: the ROA maxLength idea, RFC 6811
 * §3, without the PKI). `0` when the route carries no verified
 * origin record.
 */
int32_t lr_route_lrxp_origin_max_valid_len(lr_route_t route, uint8_t *out);

/**
 * The absolute timestamp after which downstream speakers stop
 * trusting the record (design §5.3). `0` when the route carries
 * no verified origin record.
 */
int32_t lr_route_lrxp_origin_expiry(lr_route_t route, uint32_t *out);

/**
 * Create a new router instance.
 */
lr_router_t lr_router_new(void);

/**
 * Destroy a router instance. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been returned by `lr_router_new` and not yet destroyed.
 */
void lr_router_destroy(lr_router_t r);

/**
 * Add a BGP session. Returns 0 on success, negative on error. The session
 * handle is written to `out_handle`.
 *
 * Graceful restart (RFC 4724) is enabled with a 120 s restart time;
 * Long-Lived Graceful Restart (RFC 9494) is disabled. Use
 * [`lr_router_add_bgp_session_ext`] to configure both.
 */
int32_t lr_router_add_bgp_session(lr_router_t r,
                                  uint32_t local_as,
                                  uint32_t peer_as,
                                  uint32_t local_bgp_id,
                                  uint16_t hold_time,
                                  uint16_t keepalive,
                                  uint8_t asn4,
                                  uint64_t *out_handle);

/**
 * Extended session creation with graceful-restart knobs.
 *
 * - `graceful_restart` / `gr_restart_time`: RFC 4724 advertisement and
 *   stale-route retention (seconds; restart time is clamped to 12 bits).
 * - `long_lived_gr` / `llgr_stale_time`: RFC 9494 Long-Lived Graceful
 *   Restart — LLGR requires GR per RFC 9494 §4.1, so when
 *   `long_lived_gr` is set with `graceful_restart` clear the LLGR
 *   capability is not advertised.
 * - `llgr_max_stale_time`: optional local cap (seconds) on the stale time
 *   received from the peer; 0 disables the cap (RFC 9494 §4.2).
 */
int32_t lr_router_add_bgp_session_ext(lr_router_t r,
                                      uint32_t local_as,
                                      uint32_t peer_as,
                                      uint32_t local_bgp_id,
                                      uint16_t hold_time,
                                      uint16_t keepalive,
                                      uint8_t asn4,
                                      uint8_t graceful_restart,
                                      uint16_t gr_restart_time,
                                      uint8_t long_lived_gr,
                                      uint32_t llgr_stale_time,
                                      uint32_t llgr_max_stale_time,
                                      uint64_t *out_handle);

/**
 * Push bytes from the peer transport into a session.
 *
 * # Safety
 * `bytes` must be a valid pointer to `len` bytes.
 */
int32_t lr_router_feed_input(lr_router_t r, uint64_t session, const uint8_t *bytes, uintptr_t len);

/**
 * Drain bytes from a session to send to the peer transport.
 *
 * # Safety
 * `out` must point to a valid `lr_bytes_t` slot.
 */
int32_t lr_router_drain_output(lr_router_t r, uint64_t session, struct lr_bytes_t *out);

/**
 * Advance the router clock.
 */
int32_t lr_router_tick(lr_router_t r, uint64_t now_ms);

/**
 * Start a session: drives the protocol FSM into operation (BGP:
 * ManualStart + TransportOpen). Call once the transport is connected.
 */
int32_t lr_router_start_session(lr_router_t r, uint64_t session);

int32_t lr_router_close_session(lr_router_t r, uint64_t session);

int32_t lr_router_shutdown_session(lr_router_t r, uint64_t session);

int32_t lr_router_remove_redistribution_pipe(lr_router_t r, int32_t source, int32_t target);

int32_t lr_router_adj_rib_in_snapshot(lr_router_t r, uint64_t session, struct lr_bytes_t *out);

int32_t lr_router_ospf_set_area_type(lr_router_t r, uint32_t area_id, int32_t kind);

int32_t lr_router_set_ospf_sr_receive(lr_router_t r, uint8_t on);

uint8_t lr_router_ospf_sr_receive(lr_router_t r);

int32_t lr_router_set_ospf_srv6_receive(lr_router_t r, uint8_t on);

uint8_t lr_router_ospf_srv6_receive(lr_router_t r);

int32_t lr_router_set_ospf_v3_extended_lsas(lr_router_t r, uint8_t on);

uint8_t lr_router_ospf_v3_extended_lsas(lr_router_t r);

/**
 * Set the per-prefix RFC 4271 MRAI interval for a BGP session.
 *
 * A zero interval disables batching and flushes any pending UPDATEs.
 */
int32_t lr_router_set_mrai(lr_router_t r, uint64_t session, uint64_t interval_ms);

/**
 * Enable or disable RFC 7911 Add-Path on one BGP session.
 *
 * Must be called after `lr_router_add_bgp_session*` and before
 * `lr_router_start_session` — the capability is negotiated in OPEN.
 * `enabled` is 0 (off) or non-zero (on).
 */
int32_t lr_router_set_add_path(lr_router_t r, uint64_t session, uint8_t enabled);

/**
 * Set how many paths per prefix the RFC 7911 decision process keeps in
 * Loc-RIB and advertises to Add-Path peers (router-wide).
 *
 * Values below 1 are clamped to 1 (single-path). Takes effect for
 * sessions whose Add-Path capability was negotiated.
 */
int32_t lr_router_set_add_path_max_paths(lr_router_t r, uint32_t max_paths);

/**
 * Enable or disable the RFC 8212 default eBGP route behaviors
 * (router-wide).
 *
 * When enabled, an external BGP session (eBGP or a confederation
 * boundary) with no explicit import policy declared via
 * `lr_router_set_session_policy` discards received routes, and one
 * with no export policy advertises nothing (RFC 8212 §3). `enabled`
 * is 0 (off — the RFC 4271 default-accept) or non-zero (on).
 */
int32_t lr_router_set_ebgp_requires_policy(lr_router_t r, uint8_t enabled);

/**
 * Enable or disable FRR `bgp enforce-first-as` (W2.2).
 *
 * When on, an UPDATE received from an external BGP peer (eBGP or a
 * confederation boundary) whose AS_PATH leftmost sequence segment's
 * first AS is not the peer's negotiated AS is rejected before the
 * Adj-RIB-In. When off (the default — `no bgp enforce-first-as`),
 * the route is admitted subject to the ordinary policy and safety
 * checks. `enabled` is 0 (off) or non-zero (on).
 */
int32_t lr_router_set_enforce_first_as(lr_router_t r, uint8_t enabled);

/**
 * Declare which directions of a BGP session carry an explicit policy
 * (RFC 8212 §3).
 *
 * `import`/`export` are 0 (no policy — the direction is subject to
 * the RFC 8212 default deny when enabled) or non-zero (explicit
 * policy attached; the policy itself runs through the hook chain).
 * Call after `lr_router_add_bgp_session*`; unknown handles fail with
 * -2 and set the last-error string.
 */
int32_t lr_router_set_session_policy(lr_router_t r,
                                     uint64_t session,
                                     uint8_t import,
                                     uint8_t export_);

/**
 * Configure RFC 5549 Extended Next-Hop on a BGP session.
 *
 * `tuples` points to `count` 5-byte records, each laid out as
 * `<NLRI AFI:2 (big-endian), NLRI SAFI:1, Nexthop AFI:2 (big-endian)>`.
 * The canonical tuple is `00 01 01 00 02` — IPv4 unicast NLRI resolved
 * over an IPv6 next-hop. Pass `count = 0` to clear the configuration.
 * (This is the FFI input layout, not the wire form: RFC 5549 §4
 * encodes the capability on the wire as 6-byte tuples with a 2-octet
 * SAFI — librouting performs that conversion internally.)
 *
 * Must be called after `lr_router_add_bgp_session*` and before
 * `lr_router_start_session` — the capability is negotiated in OPEN.
 *
 * `count` must not exceed [`MAX_EXT_NEXT_HOP_TUPLES`]; larger values are
 * rejected with -3 (the cap keeps `count * 5` free of overflow before the
 * caller's memory is read).
 *
 * # Safety
 * `tuples` must point to at least `count * 5` readable bytes when
 * `count > 0`.
 */
int32_t lr_router_set_extended_next_hop(lr_router_t r,
                                        uint64_t session,
                                        const uint8_t *tuples,
                                        uintptr_t count);

/**
 * Override the MP-BGP address families advertised in OPEN.
 *
 * `families` points to `count` 4-byte records, each laid out as
 * `<AFI:2 (big-endian), reserved:1, SAFI:1>` — the same encoding used
 * by the RFC 4760 multiprotocol capability. The two well-known values
 * are `00 01 00 01` (IPv4 unicast) and `00 02 00 01` (IPv6 unicast).
 *
 * Must be called before `lr_router_start_session`. Replaces the default
 * IPv4-unicast-only family list.
 *
 * `count` must not exceed [`MAX_MP_FAMILIES`]; larger values are rejected
 * with -3 (the cap keeps `count * 4` free of overflow before the caller's
 * memory is read).
 *
 * # Safety
 * `families` must point to at least `count * 4` readable bytes when
 * `count > 0`.
 */
int32_t lr_router_set_mp_families(lr_router_t r,
                                  uint64_t session,
                                  const uint8_t *families,
                                  uintptr_t count);

/**
 * Set the local source address for next-hop-self egress on a BGP session.
 *
 * `addr_family` is `1` for IPv4 (4 bytes) or `2` for IPv6 (16 bytes).
 * `addr_bytes` must point to the appropriate number of bytes. Must be
 * called before `lr_router_start_session`.
 *
 * # Safety
 * `addr_bytes` must point to 4 (IPv4) or 16 (IPv6) readable bytes.
 */
int32_t lr_router_set_local_address(lr_router_t r,
                                    uint64_t session,
                                    uint16_t addr_family,
                                    const uint8_t *addr_bytes,
                                    uintptr_t addr_len);

/**
 * Configure FRR `bgp default ipv4-unicast` (W2.1) for a BGP session.
 *
 * When `enabled` is non-zero (the default), IPv4 unicast is implicitly
 * active even when `lr_router_set_mp_families` did not list it. When
 * zero, IPv4 unicast must be added explicitly via
 * `lr_router_set_mp_families` to be active — the FRR
 * `no bgp default ipv4-unicast` posture. Must be called after
 * `lr_router_add_bgp_session*` and before `lr_router_start_session`;
 * unknown handles or already-established sessions fail with -2.
 */
int32_t lr_router_set_default_ipv4_unicast(lr_router_t r, uint64_t session, uint8_t enabled);

/**
 * Configure FRR `neighbor X allowas-in N` / BIRD `allow local as`
 * (W2.3) for a BGP session.
 *
 * `tolerance = 0` (the default) rejects any occurrence of the local
 * AS in a received AS_PATH (RFC 4271 §9.1.2.15). `N > 0` admits a
 * route whose AS_PATH contains the local AS up to N times (FRR
 * `allowas-in N`, default N=1). The special value `u32::MAX` admits
 * any number (FRR `allowas-any`). iBGP sessions are exempt
 * (FRR/BIRD scope the relaxation to eBGP). Must be called after
 * `lr_router_add_bgp_session*` and before `lr_router_start_session`;
 * unknown handles or already-established sessions fail with -2.
 */
int32_t lr_router_set_local_as_tolerance(lr_router_t r, uint64_t session, uint32_t tolerance);

/**
 * Configure FRR `neighbor X soft-reconfiguration inbound` (W2.4) for
 * a BGP session.
 *
 * When `enabled` is non-zero, the router retains the pre-policy
 * Adj-RIB-In for this session — the raw received routes before the
 * import hook chain runs — so [`lr_router_soft_reconfig_inbound`] can
 * re-evaluate the policy without re-fetching from the peer. Off by
 * default (FRR's default; the cost is duplicate RIB memory per peer).
 * Must be called after `lr_router_add_bgp_session*` and before
 * `lr_router_start_session`; unknown handles or already-established
 * sessions fail with -2.
 */
int32_t lr_router_set_soft_reconfig_inbound(lr_router_t r, uint64_t session, uint8_t enabled);

/**
 * FRR `clear ip bgp * soft in` (W2.4): re-evaluate the import policy
 * against the pre-policy Adj-RIB-In for `session`, replacing the
 * session's entries in the post-policy RIB with the re-imported
 * routes.
 *
 * Returns the number of routes re-evaluated (as a non-negative
 * integer), or a negative value on error (-1 for an invalid router
 * handle, -2 on unknown session handles). No-ops (returns 0) when
 * the session did not have `soft_reconfig_inbound` enabled — the
 * pre-policy RIB was not retained.
 */
int64_t lr_router_soft_reconfig_inbound(lr_router_t r, uint64_t session);

/**
 * Request an RFC 2918 route refresh from an established BGP peer.
 *
 * Returns 1 when a request was queued, 0 when the session has not negotiated
 * route refresh, and a negative value for invalid handles or inputs.
 */
int32_t lr_router_request_route_refresh(lr_router_t r,
                                        uint64_t session,
                                        uint16_t afi,
                                        uint8_t safi);

/**
 * Originate a local IPv4 route: `prefix_addr` is 4 bytes, `prefix_len` is
 * the prefix length, `next_hop` is 4 bytes or NULL. The route is injected
 * into Loc-RIB and advertised to all established BGP peers.
 *
 * `prefix_len` must be <= 32; larger values are rejected with -3 before any
 * NLRI is encoded (an out-of-range length would otherwise panic inside the
 * BGP NLRI encoder the first time the route is exported).
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must be valid pointers to
 * 4 readable bytes.
 */
int32_t lr_router_originate_v4(lr_router_t r,
                               const uint8_t *prefix_addr,
                               uint8_t prefix_len,
                               const uint8_t *next_hop);

/**
 * Originate an RFC 8277 labelled IPv4 BGP route (AFI=1, SAFI=4). The
 * label stack is supplied as a flat array of 20-bit label values; the
 * codec wraps each into a `Label` with TC=0, TTL=64, and sets the
 * bottom-of-stack bit on the last entry. Returns 0 on success, negative
 * on error.
 *
 * `prefix_len` must be <= 32 (see [`lr_router_originate_v4`]) and
 * `n_labels` must not exceed [`MAX_LABEL_STACK_DEPTH`].
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must point to 4 readable
 * bytes; `labels` must point to `n_labels` readable `uint32_t` values.
 */
int32_t lr_router_originate_labeled_v4(lr_router_t r,
                                       const uint8_t *prefix_addr,
                                       uint8_t prefix_len,
                                       const uint32_t *labels,
                                       uintptr_t n_labels,
                                       const uint8_t *next_hop);

/**
 * Originate an RFC 8277 labelled IPv6 BGP route (AFI=2, SAFI=4). See
 * [`lr_router_originate_labeled_v4`] for the label-stack semantics.
 *
 * `prefix_len` must be <= 128; larger values are rejected with -3 before
 * any NLRI is encoded.
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must point to 16 readable
 * bytes; `labels` must point to `n_labels` readable `uint32_t` values.
 */
int32_t lr_router_originate_labeled_v6(lr_router_t r,
                                       const uint8_t *prefix_addr,
                                       uint8_t prefix_len,
                                       const uint32_t *labels,
                                       uintptr_t n_labels,
                                       const uint8_t *next_hop);

/**
 * Originate a local IPv6 unicast route (AFI=2, SAFI=1): injects it into
 * Loc-RIB (ORIGIN=IGP, empty AS_PATH) and advertises it to established
 * MP-BGP peers. The v6 counterpart of [`lr_router_originate_v4`]; the
 * next-hop is carried by MP_REACH_NLRI on egress.
 *
 * Returns 0 on success, negative on error.
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must point to 16 readable
 * bytes.
 */
int32_t lr_router_originate_v6(lr_router_t r,
                               const uint8_t *prefix_addr,
                               uint8_t prefix_len,
                               const uint8_t *next_hop);

/**
 * Withdraw a locally originated IPv4 route (FRR `no network ...`): the
 * prefix leaves the originated set, the decision process re-runs (a
 * beaten peer path is restored; an empty set withdraws the prefix from
 * every session) and any redistribution-sourced copy is flushed.
 * Returns 0 when the route was withdrawn, **1 when the prefix was not
 * locally originated** (idempotent no-op, matching FRR/BIRD `no
 * network` on an absent statement — nothing changes), negative on
 * error.
 *
 * # Safety
 * `prefix_addr` must point to 4 readable bytes.
 */
int32_t lr_router_withdraw_v4(lr_router_t r, const uint8_t *prefix_addr, uint8_t prefix_len);

/**
 * Withdraw a locally originated IPv6 unicast route. See
 * [`lr_router_withdraw_v4`] for the semantics and return codes (0 =
 * withdrawn, 1 = not locally originated, negative = error).
 *
 * # Safety
 * `prefix_addr` must point to 16 readable bytes.
 */
int32_t lr_router_withdraw_v6(lr_router_t r, const uint8_t *prefix_addr, uint8_t prefix_len);

/**
 * Install a static IPv4 route into the Loc-RIB (BIRD `protocol
 * static`, FRR `ip route`). The route's `protocol` is
 * `Protocol::Static` and its admin distance is 1, so it wins over
 * every dynamic protocol except Connected. When `next_hop` is NULL,
 * the route is a blackhole (FRR `Null0`, BIRD `blackhole`). Returns
 * 0 on success, negative on error.
 *
 * `metric` is the per-route metric within the static protocol
 * (FRR's `metric` keyword on `ip route`); lower wins. `tag` is an
 * optional 32-bit route tag carried through redistribution pipes;
 * pass `0` when not set.
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must be valid
 * pointers to 4 readable bytes.
 */
int32_t lr_router_install_static_v4(lr_router_t r,
                                    const uint8_t *prefix_addr,
                                    uint8_t prefix_len,
                                    const uint8_t *next_hop,
                                    uint32_t metric,
                                    uint32_t tag);

/**
 * Install a static IPv6 route into the Loc-RIB. The v6 counterpart
 * of [`lr_router_install_static_v4`]; see that function for the
 * semantics. `prefix_len` must be <= 128.
 *
 * # Safety
 * `prefix_addr` and `next_hop` (when non-NULL) must be valid
 * pointers to 16 readable bytes.
 */
int32_t lr_router_install_static_v6(lr_router_t r,
                                    const uint8_t *prefix_addr,
                                    uint8_t prefix_len,
                                    const uint8_t *next_hop,
                                    uint32_t metric,
                                    uint32_t tag);

/**
 * Withdraw a previously-installed static IPv4 route. Returns 0 when
 * a static route was removed, **1 when the prefix was not a static
 * route** (idempotent no-op, matching `unoriginate`'s contract),
 * negative on error.
 *
 * # Safety
 * `prefix_addr` must point to 4 readable bytes.
 */
int32_t lr_router_uninstall_static_v4(lr_router_t r,
                                      const uint8_t *prefix_addr,
                                      uint8_t prefix_len);

/**
 * Withdraw a previously-installed static IPv6 route. The v6
 * counterpart of [`lr_router_uninstall_static_v4`].
 *
 * # Safety
 * `prefix_addr` must point to 16 readable bytes.
 */
int32_t lr_router_uninstall_static_v6(lr_router_t r,
                                      const uint8_t *prefix_addr,
                                      uint8_t prefix_len);

/**
 * Query the kernel's MPLS platform-labels capability (Linux only).
 * Returns the value of `/proc/sys/net/mpls/platform_labels` (0 when
 * MPLS routing is not enabled, 16 or 20 when it is). On non-Linux
 * platforms this always returns 0.
 */
uint32_t lr_mpls_platform_labels(void);

/**
 * Number of routes currently in Loc-RIB.
 */
int64_t lr_router_rib_len(lr_router_t r);

/**
 * Dump the Loc-RIB as a text table (one route per line). The caller owns
 * the returned bytes and must free them with `lr_bytes_free`.
 *
 * # Safety
 * `out` must point to a valid `lr_bytes_t` slot.
 */
int32_t lr_router_rib_dump(lr_router_t r, struct lr_bytes_t *out);

/**
 * Dump every session's operational summary as a text table (one line
 * per session: handle, kind, ASNs, state, establishment, peer BGP id,
 * negotiated hold time, Adj-RIB-In size). The caller owns the returned
 * bytes and must free them with `lr_bytes_free`.
 *
 * # Safety
 * `out` must point to a valid `lr_bytes_t` slot.
 */
int32_t lr_router_sessions_dump(lr_router_t r, struct lr_bytes_t *out);

/**
 * Add one ROA entry to the router's ROA table (RFC 6482 §3 /
 * RFC 6811 §2). The router uses the table when a route is
 * imported and `lr_router_set_roa_validate(r, 1)` is set; the
 * filter DSL's `roa.state` accessor reads the same table.
 *
 * Parameters:
 * - `r`: router handle (from [`lr_router_new`]).
 * - `prefix_v4` / `prefix_v6`: the authorized prefix's address
 *   bytes. For IPv4, pass the first 4 bytes of `prefix_v4` and
 *   leave `prefix_v6` NULL. For IPv6, pass the 16-byte IPv6
 *   address through `prefix_v6` and leave `prefix_v4` NULL.
 * - `prefix_len`: the prefix length (0..=32 for v4, 0..=128 for v6).
 * - `max_length`: the maximum authorized prefix length (>=
 *   `prefix_len`, <= family width). Pass `0` to default to the
 *   exact prefix length.
 * - `asn`: the authorized origin AS (u32). AS 0 marks a
 *   blackhole-range ROA (RFC 6483 §4); it never matches a real
 *   origin AS but produces `Invalid` for any route under the
 *   prefix.
 *
 * Returns 0 on success, negative on error.
 *
 * # Safety
 * `r` must be a valid `lr_router_t`. `prefix_v4` (when non-NULL)
 * must point at 4 readable bytes; `prefix_v6` (when non-NULL)
 * must point at 16 readable bytes.
 */
int32_t lr_router_add_roa_entry(lr_router_t r,
                                const uint8_t *prefix_v4,
                                const uint8_t *prefix_v6,
                                uint8_t prefix_len,
                                uint8_t max_length,
                                uint32_t asn);

/**
 * Toggle RFC 6811 §2 prefix-origin validation on (1) or off (0).
 * When on, every received BGP UPDATE is validated against the
 * router's ROA table at import time; routes whose origin AS is
 * not authorized are rejected.
 *
 * Returns 0 on success, negative on error.
 *
 * # Safety
 * `r` must be a valid `lr_router_t`.
 */
int32_t lr_router_set_roa_validate(lr_router_t r, uint8_t enable);

/**
 * Construct a fresh `RtrClient` (RFC 8210 §8.1 cold start — no
 * session memory, protocol version starts at RTR_VERSION_MAX).
 */
lr_rtr_client_t lr_rtr_client_new(void);

/**
 * Drop a boxed `RtrClient`. Safe to call with NULL.
 *
 * # Safety
 * `c` must have been produced by `lr_rtr_client_new` and not already
 * freed.
 */
void lr_rtr_client_free(lr_rtr_client_t c);

/**
 * The protocol version currently spoken (post-§7 downgrade).
 * Returns 0 on a NULL handle.
 *
 * # Safety
 * `c` must be a valid RtrClient handle.
 */
uint8_t lr_rtr_client_version(lr_rtr_client_t c);

/**
 * The remembered session ID (None until the first Cache Response).
 * Writes the session ID to `*out_session` and returns 1 if present,
 * 0 if absent (or NULL handle).
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `out_session` must point to
 * a writable `uint16_t`.
 */
uint8_t lr_rtr_client_session_id(lr_rtr_client_t c, uint16_t *out_session);

/**
 * The serial of the last completed sync. Writes to `*out_serial`
 * and returns 1 if present, 0 if absent (or NULL handle).
 *
 * # Safety
 * See [`lr_rtr_client_session_id`].
 */
uint8_t lr_rtr_client_serial(lr_rtr_client_t c, uint32_t *out_serial);

/**
 * The current phase name (diagnostics: "awaiting-reset",
 * "awaiting-serial", "receiving", "synced"). Writes a NUL-terminated
 * string to `out_buf` (capacity `cap`); returns the length needed
 * (excluding NUL) — call with `cap=0` to size.
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `out_buf` must point to
 * writable bytes (NULL only when `cap == 0`).
 */
uintptr_t lr_rtr_client_phase_name(lr_rtr_client_t c, uint8_t *out_buf, uintptr_t cap);

/**
 * The §6 timing intervals in effect (refresh, retry, expire —
 * seconds). Writes to the three out-pointers. Returns 0 on success,
 * `LR_ERR_NULL` on a NULL client or NULL out-pointers.
 *
 * # Safety
 * `c` must be a valid RtrClient handle. The out-pointers must point
 * to writable `uint32_t` values.
 */
int32_t lr_rtr_client_intervals(lr_rtr_client_t c,
                                uint32_t *out_refresh,
                                uint32_t *out_retry,
                                uint32_t *out_expire);

/**
 * Override the initial §6 intervals (refresh, retry, expire —
 * seconds). The embedder calls this once at construction from its
 * configuration; a v1+ cache replaces all three from every
 * End-of-Data PDU (§6), so this only shapes the behaviour before
 * the first End of Data and for v0 caches.
 *
 * # Safety
 * `c` must be a valid RtrClient handle.
 */
int32_t lr_rtr_client_set_intervals(lr_rtr_client_t c,
                                    uint32_t refresh,
                                    uint32_t retry,
                                    uint32_t expire);

/**
 * Bytes to transmit when the transport comes up (§8.1): a Serial
 * Query when the client remembers an unexpired session, a Reset
 * Query otherwise. Writes the wire bytes to `*out`.
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `out` must point to a
 * writable `lr_bytes_t`.
 */
int32_t lr_rtr_client_on_connect(lr_rtr_client_t c, struct lr_bytes_t *out);

/**
 * Run the §6 timing rules at `now_ms`. Returns the `ClientStep`
 * projection: refresh polls while synced, data-expiry reporting
 * once the expire interval passes without a successful sync.
 *
 * Writes the step's `synced` / `drop` / `expired` flags to the
 * out-struct; the wire bytes are written to `out_step.send_bytes`
 * (caller frees with `lr_bytes_free`).
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `out_step` must point to a
 * writable `lr_rtr_client_step_t`.
 */
int32_t lr_rtr_client_poll(lr_rtr_client_t c,
                           uint64_t now_ms,
                           struct lr_rtr_client_step_t *out_step);

/**
 * Decode one RTR PDU from `data` and feed it to the client.
 * Returns the `ClientStep` projection. This is the receive-side
 * entry point for the RTR protocol (RFC 8210 §5/§8.2).
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `data` must point to `len`
 * readable bytes. `out_step` must point to a writable
 * `lr_rtr_client_step_t`.
 */
int32_t lr_rtr_client_on_pdu_raw(lr_rtr_client_t c,
                                 const uint8_t *data,
                                 uintptr_t len,
                                 uint64_t now_ms,
                                 struct lr_rtr_client_step_t *out_step);

/**
 * Read the authoritative ROA record set after the last completed
 * sync, sorted for deterministic snapshots. Writes the entries to
 * `out_entries` (a flat `lr_roa_entry_t` array of capacity `cap`).
 * Returns the number of entries (caller-allocates pattern: call
 * with `cap=0` to size, then again to fill).
 *
 * # Safety
 * `c` must be a valid RtrClient handle. `out_entries` must point
 * to writable `lr_roa_entry_t` values (NULL only when `cap == 0`).
 */
uintptr_t lr_rtr_client_snapshot(lr_rtr_client_t c,
                                 struct lr_roa_entry_t *out_entries,
                                 uintptr_t cap);

/**
 * Encode `pdu` at protocol `version` and write the wire bytes to
 * `*out`. The version must satisfy `RtrPdu::min_version` — otherwise
 * the wire form would be a cache-side protocol violation and the
 * function returns `LR_ERR_OTHER`.
 *
 * # Safety
 * `pdu` must be a valid handle. `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_rtr_pdu_encode(lr_rtr_pdu_t pdu, uint8_t version, struct lr_bytes_t *out);

/**
 * Convenience encoder returning a fresh `lr_bytes_t`. Same contract
 * as [`lr_rtr_pdu_encode`].
 *
 * # Safety
 * `pdu` must be a valid handle. `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_rtr_pdu_encode_vec(lr_rtr_pdu_t pdu, uint8_t version, struct lr_bytes_t *out);

/**
 * Decode one PDU from `data`. On success writes a freshly-allocated
 * `lr_rtr_pdu_t` to `*out_pdu`, the protocol version to `*out_version`
 * and the bytes consumed to `*out_consumed`. Returns 0 on success,
 * `LR_ERR_NULL` on a NULL pointer, `LR_ERR_OTHER` on a decode error
 * (the last-error string is set), and 1 when the buffer is
 * incomplete (more bytes needed — the caller should read more and
 * retry).
 *
 * # Safety
 * `data` must point to `len` readable bytes. The three out-pointers
 * must point to writable memory of the right type.
 */
int32_t lr_rtr_pdu_decode(const uint8_t *data,
                          uintptr_t len,
                          lr_rtr_pdu_t *out_pdu,
                          uint8_t *out_version,
                          uintptr_t *out_consumed);

/**
 * Drop a boxed `RtrPdu`. Safe to call with NULL.
 *
 * # Safety
 * `pdu` must have been produced by a `lr_rtr_pdu_*` constructor and
 * must not be used after this call.
 */
void lr_rtr_pdu_free(lr_rtr_pdu_t pdu);

/**
 * Write the PDU's RFC §5.1.2 type code to `*out`. Returns 0 on
 * success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * `pdu` must be a valid handle. `out` must point to writable `uint8_t`.
 */
int32_t lr_rtr_pdu_type(lr_rtr_pdu_t pdu, uint8_t *out);

/**
 * Write the PDU's minimum required protocol version to `*out`.
 *
 * # Safety
 * See [`lr_rtr_pdu_type`].
 */
int32_t lr_rtr_pdu_min_version(lr_rtr_pdu_t pdu, uint8_t *out);

/**
 * Build a Serial Notify PDU (RFC 8210 §5.2).
 */
lr_rtr_pdu_t lr_rtr_pdu_serial_notify(uint16_t session_id, uint32_t serial);

/**
 * Build a Serial Query PDU (RFC 8210 §5.3).
 */
lr_rtr_pdu_t lr_rtr_pdu_serial_query(uint16_t session_id, uint32_t serial);

/**
 * Build a Reset Query PDU (RFC 8210 §5.4).
 */
lr_rtr_pdu_t lr_rtr_pdu_reset_query(void);

/**
 * Build a Cache Response PDU (RFC 8210 §5.5).
 */
lr_rtr_pdu_t lr_rtr_pdu_cache_response(uint16_t session_id);

/**
 * Build a Cache Reset PDU (RFC 8210 §5.9).
 */
lr_rtr_pdu_t lr_rtr_pdu_cache_reset(void);

/**
 * Build an IPv4 Prefix PDU (RFC 8210 §5.6). `prefix_v4` points to 4
 * readable bytes; `prefix_len` and `max_length` are the prefix and
 * ROA max lengths. Pass `announce = 1` for an announcement, `0` for
 * a withdrawal.
 *
 * # Safety
 * `prefix_v4` must point to 4 readable bytes (NULL only when
 * `prefix_len == 0` is desired — but the codec requires a real
 * prefix, so NULL is rejected).
 */
lr_rtr_pdu_t lr_rtr_pdu_ipv4_prefix(uint8_t announce,
                                    const uint8_t *prefix_v4,
                                    uint8_t prefix_len,
                                    uint8_t max_length,
                                    uint32_t asn);

/**
 * Build an IPv6 Prefix PDU (RFC 8210 §5.7). `prefix_v6` points to 16
 * readable bytes.
 *
 * # Safety
 * `prefix_v6` must point to 16 readable bytes.
 */
lr_rtr_pdu_t lr_rtr_pdu_ipv6_prefix(uint8_t announce,
                                    const uint8_t *prefix_v6,
                                    uint8_t prefix_len,
                                    uint8_t max_length,
                                    uint32_t asn);

/**
 * Build an End-of-Data PDU (RFC 8210 §5.8). The timing intervals are
 * optional per §5.8 — pass 0 to omit (the v0 wire form omits them;
 * v1+ always carries them and 0 means "use the configured default").
 */
lr_rtr_pdu_t lr_rtr_pdu_end_of_data(uint16_t session_id,
                                    uint32_t serial,
                                    uint32_t refresh_interval,
                                    uint32_t retry_interval,
                                    uint32_t expire_interval);

/**
 * Build a Router Key PDU (RFC 8210 §5.10, v1+). `ski` points to 20
 * readable bytes; `spki` points to `spki_len` readable bytes (the
 * full DER subjectPublicKeyInfo).
 *
 * # Safety
 * `ski` must point to 20 readable bytes; `spki` must point to
 * `spki_len` readable bytes (NULL only when `spki_len == 0`).
 */
lr_rtr_pdu_t lr_rtr_pdu_router_key(uint8_t announce,
                                   const uint8_t *ski,
                                   uint32_t asn,
                                   const uint8_t *spki,
                                   uintptr_t spki_len);

/**
 * Build an Error Report PDU (RFC 8210 §5.11). `erroneous_pdu` points
 * to `erroneous_pdu_len` readable bytes (NULL when `len == 0`);
 * `error_text` is a NUL-terminated UTF-8 string (NULL when absent).
 *
 * # Safety
 * `erroneous_pdu` must point to `erroneous_pdu_len` readable bytes
 * (NULL only when `erroneous_pdu_len == 0`). `error_text` must be a
 * NUL-terminated UTF-8 string or NULL.
 */
lr_rtr_pdu_t lr_rtr_pdu_error_report(uint16_t error_code,
                                     const uint8_t *erroneous_pdu,
                                     uintptr_t erroneous_pdu_len,
                                     const char *error_text);

/**
 * Build an ASPA PDU (v2+, SIDROPS ASPA profile). `providers` points
 * to `providers_count` readable `uint32_t` values.
 *
 * # Safety
 * `providers` must point to `providers_count` readable `uint32_t`
 * values (NULL only when `providers_count == 0`).
 */
lr_rtr_pdu_t lr_rtr_pdu_aspa(uint8_t announce,
                             uint32_t customer_asn,
                             const uint32_t *providers,
                             uintptr_t providers_count);

/**
 * Read the session_id of a Serial Notify / Serial Query / Cache
 * Response / End-of-Data PDU. Returns 0 on a NULL handle or a
 * non-matching variant (the caller can check the type first via
 * [`lr_rtr_pdu_type`]).
 *
 * # Safety
 * `pdu` must be a valid handle. `out` must point to writable `uint16_t`.
 */
int32_t lr_rtr_pdu_session_id(lr_rtr_pdu_t pdu, uint16_t *out);

/**
 * Read the serial number of a Serial Notify / Serial Query / End-of-
 * Data PDU.
 *
 * # Safety
 * See [`lr_rtr_pdu_session_id`].
 */
int32_t lr_rtr_pdu_serial(lr_rtr_pdu_t pdu, uint32_t *out);

/**
 * Read the announce flag of an IPv4 Prefix / IPv6 Prefix / Router
 * Key / ASPA PDU. Writes 1 for announcement, 0 for withdrawal.
 *
 * # Safety
 * See [`lr_rtr_pdu_session_id`].
 */
int32_t lr_rtr_pdu_announce(lr_rtr_pdu_t pdu, uint8_t *out);

/**
 * Read the prefix of an IPv4 Prefix PDU. Writes 4 bytes of prefix
 * address to `out_prefix_v4` and the prefix length to
 * `*out_prefix_len`.
 *
 * # Safety
 * `out_prefix_v4` must point to 4 writable bytes; `out_prefix_len`
 * must point to a writable `uint8_t`.
 */
int32_t lr_rtr_pdu_ipv4_prefix_fields(lr_rtr_pdu_t pdu,
                                      uint8_t *out_prefix_v4,
                                      uint8_t *out_prefix_len,
                                      uint8_t *out_max_length,
                                      uint32_t *out_asn);

/**
 * Read the prefix of an IPv6 Prefix PDU. Writes 16 bytes of prefix
 * address to `out_prefix_v6`.
 *
 * # Safety
 * `out_prefix_v6` must point to 16 writable bytes; the other three
 * out-pointers must point to writable memory of the right type.
 */
int32_t lr_rtr_pdu_ipv6_prefix_fields(lr_rtr_pdu_t pdu,
                                      uint8_t *out_prefix_v6,
                                      uint8_t *out_prefix_len,
                                      uint8_t *out_max_length,
                                      uint32_t *out_asn);

/**
 * Read the End-of-Data timing intervals. Writes 1 to
 * `*out_present` when the intervals are present (v1+), 0 when
 * absent (v0). When present, the three interval values are written
 * to the matching out-pointers; when absent the out-pointers are
 * left untouched.
 *
 * # Safety
 * All four out-pointers must point to writable memory of the right
 * type.
 */
int32_t lr_rtr_pdu_end_of_data_intervals(lr_rtr_pdu_t pdu,
                                         uint8_t *out_present,
                                         uint32_t *out_refresh,
                                         uint32_t *out_retry,
                                         uint32_t *out_expire);

/**
 * Read the Router Key PDU's SKI (20 bytes) and ASN. `out_ski` must
 * point to 20 writable bytes.
 *
 * # Safety
 * `out_ski` must point to 20 writable bytes; `out_asn` must point
 * to a writable `uint32_t`. The SPKI bytes are returned via
 * `out_spki` as a `lr_bytes_t` (caller frees with `lr_bytes_free`).
 */
int32_t lr_rtr_pdu_router_key_fields(lr_rtr_pdu_t pdu,
                                     uint8_t *out_ski,
                                     uint32_t *out_asn,
                                     struct lr_bytes_t *out_spki);

/**
 * Read the Error Report PDU's error code (RFC 8210 §12).
 *
 * # Safety
 * `out` must point to a writable `uint16_t`.
 */
int32_t lr_rtr_pdu_error_code(lr_rtr_pdu_t pdu, uint16_t *out);

/**
 * Read the Error Report PDU's erroneous-PDU bytes (caller frees with
 * `lr_bytes_free`).
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_rtr_pdu_erroneous_pdu(lr_rtr_pdu_t pdu, struct lr_bytes_t *out);

/**
 * Read the Error Report PDU's error text. Writes a freshly-allocated
 * `lr_bytes_t` to `*out` carrying the UTF-8 text (without trailing
 * NUL) when present, or sets `out->ptr = NULL` when absent.
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_rtr_pdu_error_text(lr_rtr_pdu_t pdu, struct lr_bytes_t *out);

/**
 * Read the ASPA PDU's customer ASN.
 *
 * # Safety
 * `out` must point to a writable `uint32_t`.
 */
int32_t lr_rtr_pdu_customer_asn(lr_rtr_pdu_t pdu, uint32_t *out);

/**
 * Read the ASPA PDU's provider ASNs as a flat `uint32_t` array
 * (caller-supplied buffer). Writes the count to `*out_count` and
 * returns 0 on success. If the buffer is too small, writes the
 * required count to `*out_count` and returns `LR_ERR_OTHER` (the
 * last-error string is set).
 *
 * # Safety
 * `out_providers` must point to `cap` writable `uint32_t` values
 * (NULL is allowed only when `cap == 0`, in which case the function
 * only reports the count). `out_count` must point to a writable
 * `uintptr_t`.
 */
int32_t lr_rtr_pdu_providers(lr_rtr_pdu_t pdu,
                             uint32_t *out_providers,
                             uintptr_t cap,
                             uintptr_t *out_count);

/**
 * Write the BIRD-style display name for PDU type `ty` to
 * `*out_name`. The pointer is valid until the next FFI call on this
 * thread. Returns 0 on success, `LR_ERR_NULL` on a NULL out-pointer,
 * `LR_ERR_INVALID_HANDLE` when `ty` is not a known type code.
 *
 * # Safety
 * `out_name` must point to a writable `const char*`.
 */
int32_t lr_rtr_pdu_type_name(uint8_t ty, const char **out_name);

/**
 * Write the minimum PDU length for type `ty` to `*out`. Returns 0 on
 * success, `LR_ERR_INVALID_HANDLE` when `ty` is unknown.
 *
 * # Safety
 * `out` must point to a writable `uintptr_t`.
 */
int32_t lr_rtr_pdu_type_min_len(uint8_t ty, uintptr_t *out);

/**
 * Convert a wire type byte to the canonical RtrPduType tag, or
 * return `LR_ERR_INVALID_HANDLE` when the type is unknown. Writes
 * the type code back to `*out` (so a caller passing a reserved type
 * like 5 still gets the same byte back, but the call errors).
 *
 * Useful for a C consumer that wants to validate the type before
 * dispatching on it.
 *
 * # Safety
 * `out` must point to a writable `uint8_t`.
 */
int32_t lr_rtr_pdu_type_from_u8(uint8_t ty, uint8_t *out);

/**
 * Write the BIRD-style diagnostic name for error code `code` to
 * `*out_name`. The pointer is valid until the next FFI call on this
 * thread. Returns 0 on success, `LR_ERR_INVALID_HANDLE` when `code`
 * is unknown.
 *
 * # Safety
 * `out_name` must point to a writable `const char*`.
 */
int32_t lr_rtr_error_code_name(uint16_t code, const char **out_name);

/**
 * Write 1 to `*out` when `code` is a fatal error (everything except
 * No Data Available per RFC §12), 0 otherwise.
 *
 * # Safety
 * `out` must point to a writable `uint8_t`.
 */
int32_t lr_rtr_error_code_is_fatal(uint16_t code, uint8_t *out);

/**
 * Validate that `code` is a known RTR error code. Returns 0 on
 * success, `LR_ERR_INVALID_HANDLE` when unknown.
 */
int32_t lr_rtr_error_code_from_u16(uint16_t code);

/**
 * Construct a `Seg6Route` (RFC 8754 §2 — `seg6` lwtunnel encap
 * route) from an IPv6 prefix and an SRH handle. The default encap
 * mode is `Encap` (mirrors `ip route add ... encap seg6 mode encap
 * ...` and is what most operators want); pass the SRH by value
 * (the handle is borrowed — the constructor clones the inner `Srh`).
 *
 * Returns NULL on a NULL `srh` or when `prefix` carries an IPv4
 * address (the `seg6` lwtunnel only accepts IPv6 routes — `ip -6
 * route add ... encap seg6 ...` rejects an IPv4 prefix at the
 * iproute2 layer too). The error code is recorded in the
 * thread-local last-error string — recover it with
 * [`lr_seg6_route_err_code`].
 *
 * # Safety
 * `srh` must be a valid `lr_srv6_srh_t` produced by
 * `lr_srv6_srh_new` / `lr_srv6_srh_new_with_segments_left` and not
 * already freed.
 */
lr_seg6_route_t lr_seg6_route_new(struct lr_prefix_t prefix, lr_srv6_srh_t srh);

/**
 * Set the encap mode on a `Seg6Route` (RFC 8754 §2 — `Inline`
 * inserts the SRH into the existing IPv6 packet; `Encap` wraps it
 * in an outer IPv6 header carrying the SRH).
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle, `LR_ERR_OTHER`
 * on an unknown mode value (the caller passes one of
 * `LR_SEG6_ENCAP_INLINE` / `LR_SEG6_ENCAP_ENCAP`).
 *
 * # Safety
 * `r` must be a valid `lr_seg6_route_t` produced by
 * `lr_seg6_route_new` and not already freed.
 */
int32_t lr_seg6_route_set_mode(lr_seg6_route_t r, uint32_t mode);

/**
 * Set the output interface index (`RTA_OIF`) on a `Seg6Route`. The
 * kernel's `fib6_nh_init` rejects an IPv6 route that names neither
 * an egress device nor a gateway with `ENODEV`, so callers usually
 * set this. 0 means "let the kernel resolve via the gateway".
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * See [`lr_seg6_route_set_mode`].
 */
int32_t lr_seg6_route_set_if_index(lr_seg6_route_t r, uint32_t if_index);

/**
 * Drop a boxed `Seg6Route`. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_seg6_route_new` and not
 * already freed.
 */
void lr_seg6_route_free(lr_seg6_route_t r);

/**
 * Construct a `Seg6LocalRoute` (RFC 8986 §4 — `seg6local` endpoint
 * route) from a SID handle and an IANA behavior wire value (one of
 * the `lr_srv6::Behavior` wire codes — End=1, End.X=5, End.T=9, …).
 * The behavior is resolved via `Behavior::from_wire`; an unknown
 * wire value (40+ which the crate does not yet model) is rejected
 * with `LR_ERR_OTHER`.
 *
 * Returns NULL on a NULL `sid` or an unrecognized behavior. The
 * error code is recorded in the thread-local last-error string —
 * recover it with [`lr_seg6_route_err_code`].
 *
 * # Safety
 * `sid` must be a valid `lr_srv6_sid_t` produced by
 * `lr_srv6_sid_new` / `lr_srv6_locator_sid_with_tail` / ... and not
 * already freed.
 */
lr_seg6_local_route_t lr_seg6_local_route_new(lr_srv6_sid_t sid, uint16_t behavior_wire);

/**
 * Set the route-level egress interface index (`RTA_OIF`) on a
 * `Seg6LocalRoute`. Required for the install to be accepted: the
 * kernel's `fib6_nh_init` rejects a route that names neither an
 * egress device nor a gateway with `ENODEV`.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * `r` must be a valid `lr_seg6_local_route_t` produced by
 * `lr_seg6_local_route_new` and not already freed.
 */
int32_t lr_seg6_local_route_set_if_index(lr_seg6_local_route_t r, uint32_t if_index);

/**
 * Set the IPv4 next-hop (`SEG6_LOCAL_NH4` — the `End.DX4` parameter).
 * `nh4` is a 4-byte buffer in network byte order.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle or a NULL
 * `nh4` pointer.
 *
 * # Safety
 * `nh4` must point to 4 readable bytes (or be NULL — the call returns
 * `LR_ERR_NULL` early without reading).
 */
int32_t lr_seg6_local_route_set_nh4(lr_seg6_local_route_t r, const uint8_t *nh4);

/**
 * Set the IPv6 next-hop (`SEG6_LOCAL_NH6` — the `End.X` /
 * `End.DX6` parameter). `nh6` is a 16-byte buffer in network byte
 * order.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle or a NULL
 * `nh6` pointer.
 *
 * # Safety
 * `nh6` must point to 16 readable bytes (or be NULL — the call
 * returns `LR_ERR_NULL` early without reading).
 */
int32_t lr_seg6_local_route_set_nh6(lr_seg6_local_route_t r, const uint8_t *nh6);

/**
 * Set the input interface index (`SEG6_LOCAL_IIF`). Note: no
 * mainline kernel `seg6local` action consumes the IIF parameter
 * today — the install will fail with a descriptive error until a
 * kernel action adopts it.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * See [`lr_seg6_local_route_set_if_index`].
 */
int32_t lr_seg6_local_route_set_iif(lr_seg6_local_route_t r, uint32_t iif);

/**
 * Set the output interface index (`SEG6_LOCAL_OIF` — the
 * `End.DX2` parameter; an optional `End.X` steering parameter).
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * See [`lr_seg6_local_route_set_if_index`].
 */
int32_t lr_seg6_local_route_set_oif(lr_seg6_local_route_t r, uint32_t oif);

/**
 * Set the routing table ID (`SEG6_LOCAL_TABLE` — the `End.T`
 * parameter; also tolerated by the legacy `End.DT6` path on a
 * non-L3-master kernel). Mutually exclusive with
 * [`lr_seg6_local_route_set_vrf_table`] in practice — the encoder's
 * parameter contract check rejects a route that sets both.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * See [`lr_seg6_local_route_set_if_index`].
 */
int32_t lr_seg6_local_route_set_table(lr_seg6_local_route_t r, uint32_t table);

/**
 * Set the VRF table ID (`SEG6_LOCAL_VRFTABLE` — the `End.DT4` /
 * `End.DT46` parameter; also accepted by the L3-master-dev form of
 * `End.DT6`). Mutually exclusive with
 * [`lr_seg6_local_route_set_table`].
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle.
 *
 * # Safety
 * See [`lr_seg6_local_route_set_if_index`].
 */
int32_t lr_seg6_local_route_set_vrf_table(lr_seg6_local_route_t r, uint32_t vrf_table);

/**
 * Set the SRv6 Routing Header (`SEG6_LOCAL_SRH` — the
 * `End.B6.Insert` / `End.B6.Encaps` parameter). The SRH is the
 * same wire form a `seg6` encap route pushes (RFC 8754 §2); the
 * endpoint inserts (End.B6.Insert) or wraps (End.B6.Encaps) it
 * onto the packet at the binding-SID endpoint. The handle is
 * borrowed — the setter clones the inner `Srh`.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle or a NULL
 * `srh`.
 *
 * # Safety
 * `srh` must be a valid `lr_srv6_srh_t` produced by
 * `lr_srv6_srh_new` / `lr_srv6_srh_new_with_segments_left` and not
 * already freed.
 */
int32_t lr_seg6_local_route_set_srh(lr_seg6_local_route_t r, lr_srv6_srh_t srh);

/**
 * Drop a boxed `Seg6LocalRoute`. Safe to call with NULL.
 *
 * # Safety
 * `r` must have been produced by `lr_seg6_local_route_new` and not
 * already freed.
 */
void lr_seg6_local_route_free(lr_seg6_local_route_t r);

/**
 * Open a `NETLINK_ROUTE` socket for SRv6 route installation.
 *
 * Returns a handle on success, NULL on failure. On failure the
 * thread-local last-error string carries the `Display` form of the
 * `Seg6RouteError` and [`lr_seg6_route_err_code`] returns the
 * discriminant. The most common failure on a Linux CI runner is
 * `NotEnabled` (the kernel's `seg6_enabled` sysctl is 0); a
 * non-Linux build returns `Unsupported`.
 *
 * # Safety
 * The returned handle must be released with
 * [`lr_seg6_netlink_free`] to avoid a memory leak.
 */
lr_seg6_netlink_t lr_seg6_netlink_connect(void);

/**
 * Install a `seg6` encap route (RFC 8754 §2 — the LSP head-end:
 * push an SRH on packets matching `prefix`). The kernel's
 * `fib6_nh_init` rejects a route that names neither an egress
 * device nor a gateway, so the caller usually sets `if_index` via
 * [`lr_seg6_route_set_if_index`].
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle / route,
 * `LR_ERR_INVALID_HANDLE` on an invalid handle, and a positive
 * `LR_SEG6_ERR_*` discriminant on a backend error (recorded in the
 * last-error string too).
 *
 * # Safety
 * `nl` must be a valid `lr_seg6_netlink_t` produced by
 * `lr_seg6_netlink_connect`; `route` must be a valid
 * `lr_seg6_route_t` produced by `lr_seg6_route_new`. Both must not
 * have been freed.
 */
int32_t lr_seg6_netlink_add_seg6_route(lr_seg6_netlink_t nl, lr_seg6_route_t route);

/**
 * Delete a `seg6` encap route by prefix (the minimal
 * prefix-shaped delete iproute2 sends: `ip route del PREFIX`).
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle, and a
 * positive `LR_SEG6_ERR_*` discriminant on a backend error.
 *
 * # Safety
 * `nl` must be a valid `lr_seg6_netlink_t` produced by
 * `lr_seg6_netlink_connect`.
 */
int32_t lr_seg6_netlink_delete_seg6_route(lr_seg6_netlink_t nl, struct lr_prefix_t prefix);

/**
 * Install a `seg6local` endpoint route (RFC 8986 §4 — the LSP
 * tail-end: run `behavior` when a packet arrives addressed to
 * `sid`). The kernel's `seg6_action_table` requires a per-behavior
 * parameter set; the encoder fails fast with
 * `UnsupportedAction` for behaviors or parameter sets the kernel
 * would reject with a bare `EINVAL`.
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle / route,
 * and a positive `LR_SEG6_ERR_*` discriminant on a backend error.
 *
 * # Safety
 * `nl` must be a valid `lr_seg6_netlink_t` produced by
 * `lr_seg6_netlink_connect`; `route` must be a valid
 * `lr_seg6_local_route_t` produced by `lr_seg6_local_route_new`.
 * Both must not have been freed.
 */
int32_t lr_seg6_netlink_add_seg6local_route(lr_seg6_netlink_t nl, lr_seg6_local_route_t route);

/**
 * Delete a `seg6local` endpoint route by SID (the same minimal
 * prefix-shaped delete as `lr_seg6_netlink_delete_seg6_route`,
 * against the local table — seg6local rows are /128 SIDs).
 *
 * Returns 0 on success, `LR_ERR_NULL` on a NULL handle / sid, and
 * a positive `LR_SEG6_ERR_*` discriminant on a backend error.
 *
 * # Safety
 * `nl` must be a valid `lr_seg6_netlink_t`; `sid` must be a valid
 * `lr_srv6_sid_t` produced by `lr_srv6_sid_new` / siblings.
 */
int32_t lr_seg6_netlink_delete_seg6local_route(lr_seg6_netlink_t nl, lr_srv6_sid_t sid);

/**
 * Write the most recent request bytes (the diagnostic for "the
 * kernel rejected this and I need to see what \"this\" was" —
 * hex-dump it on failure and compare against a reference
 * implementation's bytes) to `*out`. The bytes are owned by the
 * caller and must be released with [`lr_bytes_free`].
 *
 * Returns 0 on success (including the no-bytes case — `out` is set
 * to an empty `lr_bytes_t`), `LR_ERR_NULL` on a NULL handle / out
 * pointer.
 *
 * # Safety
 * `nl` must be a valid `lr_seg6_netlink_t`; `out` must point to a
 * writable `lr_bytes_t` (uninitialized is fine — the function writes
 * the whole struct).
 */
int32_t lr_seg6_netlink_last_request_bytes(lr_seg6_netlink_t nl, struct lr_bytes_t *out);

/**
 * Write the most recent response bytes (the raw NAK, extack
 * attributes included, for the same purpose as
 * [`lr_seg6_netlink_last_request_bytes`]) to `*out`. The bytes are
 * owned by the caller and must be released with [`lr_bytes_free`].
 *
 * Returns 0 on success (including the no-bytes case), `LR_ERR_NULL`
 * on a NULL handle / out pointer.
 *
 * # Safety
 * See [`lr_seg6_netlink_last_request_bytes`].
 */
int32_t lr_seg6_netlink_last_response_bytes(lr_seg6_netlink_t nl, struct lr_bytes_t *out);

/**
 * Drop a boxed `Seg6Netlink`. Safe to call with NULL.
 *
 * # Safety
 * `nl` must have been produced by `lr_seg6_netlink_connect` and not
 * already freed.
 */
void lr_seg6_netlink_free(lr_seg6_netlink_t nl);

/**
 * Return the discriminant of the most recent `Seg6RouteError`
 * recorded in the thread-local last-error string. The Display form
 * is parsed back into a discriminant by substring match — kept in
 * the C ABI's own surface so a future typed-error-pointer surface
 * can call into `seg6_route_err_code` directly without going
 * through the thread-local string. Returns `LR_SEG6_ERR_UNKNOWN`
 * (-1) when no seg6 error is recorded.
 *
 * This is a peek-only helper: it does not clear the last-error
 * string. Callers that need the human-readable message should still
 * call `lr_last_error`.
 */
int32_t lr_seg6_route_err_code(void);

/**
 * Return a stable, NUL-terminated name for a `Seg6RouteError`
 * discriminant. Returns `"unknown"` for an unrecognized code. The
 * returned pointer is valid until the next
 * `lr_seg6_route_err_name` call on this thread — same lifetime
 * contract as `lr_rtr_error_code_name` (the function writes the
 * name into a thread-local buffer).
 */
const char *lr_seg6_route_err_name(int32_t code);

lr_seg6_route_t lr_seg6_route_new(struct lr_prefix_t prefix, lr_srv6_srh_t srh);

int32_t lr_seg6_route_set_mode(lr_seg6_route_t r, uint32_t mode);

int32_t lr_seg6_route_set_if_index(lr_seg6_route_t r, uint32_t if_index);

void lr_seg6_route_free(lr_seg6_route_t r);

lr_seg6_local_route_t lr_seg6_local_route_new(lr_srv6_sid_t sid, uint16_t behavior_wire);

int32_t lr_seg6_local_route_set_if_index(lr_seg6_local_route_t r, uint32_t if_index);

int32_t lr_seg6_local_route_set_nh4(lr_seg6_local_route_t r, const uint8_t *nh4);

int32_t lr_seg6_local_route_set_nh6(lr_seg6_local_route_t r, const uint8_t *nh6);

int32_t lr_seg6_local_route_set_iif(lr_seg6_local_route_t r, uint32_t iif);

int32_t lr_seg6_local_route_set_oif(lr_seg6_local_route_t r, uint32_t oif);

int32_t lr_seg6_local_route_set_table(lr_seg6_local_route_t r, uint32_t table);

int32_t lr_seg6_local_route_set_vrf_table(lr_seg6_local_route_t r, uint32_t vrf_table);

int32_t lr_seg6_local_route_set_srh(lr_seg6_local_route_t r, lr_srv6_srh_t srh);

void lr_seg6_local_route_free(lr_seg6_local_route_t r);

lr_seg6_netlink_t lr_seg6_netlink_connect(void);

int32_t lr_seg6_netlink_add_seg6_route(lr_seg6_netlink_t nl, lr_seg6_route_t route);

int32_t lr_seg6_netlink_delete_seg6_route(lr_seg6_netlink_t nl, struct lr_prefix_t prefix);

int32_t lr_seg6_netlink_add_seg6local_route(lr_seg6_netlink_t nl, lr_seg6_local_route_t route);

int32_t lr_seg6_netlink_delete_seg6local_route(lr_seg6_netlink_t nl, lr_srv6_sid_t sid);

int32_t lr_seg6_netlink_last_request_bytes(lr_seg6_netlink_t nl, struct lr_bytes_t *out);

int32_t lr_seg6_netlink_last_response_bytes(lr_seg6_netlink_t nl, struct lr_bytes_t *out);

void lr_seg6_netlink_free(lr_seg6_netlink_t nl);

/**
 * Add an OSPFv2 session with the library defaults: MTU 1500,
 * point-to-point network type, Normal (non-stub) area. Returns 0 with
 * the handle written to `out_handle`, `-1` on a null out pointer,
 * `-2` on an invalid router handle, `-3` when the router rejects the
 * configuration (mismatched router-id, area kind conflict, backbone
 * stub — the last-error string says which).
 *
 * # Safety
 * `out_handle` must be a writable `u64` when non-null.
 */
int32_t lr_router_add_ospf_session(lr_router_t r,
                                   uint32_t router_id,
                                   uint32_t area_id,
                                   uint64_t *out_handle);

/**
 * Add an OSPFv3 session (RFC 5340) with the library defaults. Router
 * IDs stay 32-bit and shared with OSPFv2 within one router; areas are
 * version-exclusive. Return/error codes as
 * [`lr_router_add_ospf_session`].
 *
 * # Safety
 * `out_handle` must be a writable `u64` when non-null.
 */
int32_t lr_router_add_ospfv3_session(lr_router_t r,
                                     uint32_t router_id,
                                     uint32_t area_id,
                                     uint64_t *out_handle);

/**
 * Add an OSPF session with the full knob set.
 *
 * * `version` — [`LR_OSPF_V2`] or [`LR_OSPF_V3`].
 * * `area_kind` — [`LR_AREA_NORMAL`], [`LR_AREA_STUB`],
 *   [`LR_AREA_STUB_NO_SUMMARY`], [`LR_AREA_NSSA`],
 *   [`LR_AREA_NSSA_NO_SUMMARY`]. The stub/NSSA kinds use
 *   `default_metric` for the border-router-injected default route.
 * * `mtu` — interface MTU announced in DBD packets (§10.6); 0 falls
 *   back to the 1500 default.
 * * `network_type` — [`LR_NET_PTP`] or [`LR_NET_BROADCAST`] (§9.4;
 *   broadcast gates adjacency on the elected DR/BDR, §10.4).
 * * `has_interface_ip` / `interface_ip` — our identity on the segment:
 *   the IPv4 interface address on v2 (§10.4, §12.4.1.2) or the Router
 *   ID on v3 (RFC 5340 §4.1.2). Ignored when `has_interface_ip` is 0.
 * * `has_neighbor_ip` / `neighbor_ip` — the neighbor's identity on
 *   the segment (v2 interface address / v3 Router ID), what the
 *   elected DR/BDR is compared against. Ignored when 0.
 *
 * Return codes: 0 ok, -1 null out pointer, -2 invalid handle, -3
 * malformed argument (unknown version/area kind/network type) or
 * rejected by the router, [`LR_ERR_PANIC`] on panic.
 *
 * # Safety
 * `out_handle` must be a writable `u64` when non-null.
 */
int32_t lr_router_add_ospf_session_ext(lr_router_t r,
                                       int32_t version,
                                       uint32_t router_id,
                                       uint32_t area_id,
                                       int32_t area_kind,
                                       uint32_t default_metric,
                                       uint16_t mtu,
                                       int32_t network_type,
                                       int32_t has_interface_ip,
                                       uint32_t interface_ip,
                                       int32_t has_neighbor_ip,
                                       uint32_t neighbor_ip,
                                       uint64_t *out_handle);

/**
 * Add one Babel interface session (RFC 8966). `local_addr` is the
 * 16-byte IPv6 address the interface announces in Hellos (§4.2.1) —
 * for IPv4 operation the embedder passes the v4-mapped form
 * (`::ffff:a.b.c.d`, `is_ipv6 = 0` selects the first four bytes).
 *
 * Return codes: 0 ok with the handle in `out_handle`, -1 null out
 * pointer, -2 invalid handle, [`LR_ERR_PANIC`] on panic.
 *
 * # Safety
 * `local_addr` must be a readable 16-byte array when non-null;
 * `out_handle` must be a writable `u64` when non-null.
 */
int32_t lr_router_add_babel_session(lr_router_t r,
                                    const uint8_t *local_addr,
                                    int32_t is_ipv6,
                                    uint64_t *out_handle);

/**
 * Encode an SRH from a list of SID bytes. Each SID is 16 bytes; the
 * caller passes a flat `data` of `len = n * 16` bytes. The encoded
 * SRH (RFC 8754 §2 wire form) is written to `*out`.
 *
 * Returns 0 on success, negative on error:
 * - `-1`: null pointer or `len` not a multiple of 16.
 * - `-4`: panic.
 * - `LR_ERR_CODEC` (-5): SRH encode error (set via `lr_last_error`).
 */
int32_t lr_srv6_encode_srh(const uint8_t *data, uintptr_t len, struct lr_bytes_t *out);

/**
 * Decode an SRH from `data` (RFC 8754 §2 wire form). On success,
 * writes a freshly-allocated `lr_bytes_t` to `*out` carrying the
 * segment list bytes (16 octets per SID, concatenated in wire
 * order). The TLV bytes are appended after the segment list so the
 * caller can recover the full SRH body, but the typical caller
 * only needs the segment list.
 *
 * Returns 0 on success, negative on error:
 * - `-1`: null pointer.
 * - `-3`: input too short.
 * - `-4`: panic.
 * - `LR_ERR_CODEC` (-5): SRH decode error (set via `lr_last_error`).
 */
int32_t lr_srv6_decode_srh(const uint8_t *data, uintptr_t len, struct lr_bytes_t *out);

/**
 * Look up a `Behavior` by its 16-bit wire value (RFC 8986 §9.2,
 * IANA registry). Returns 1 when the value maps to a known behavior,
 * 0 when it is unassigned. The 16-bit wire value is written to
 * `*out_value` and the behavior's mnemonic name (e.g. `"End"`,
 * `"End.X with PSP"`) is written to `*out_name` as a NUL-terminated
 * C string copied into the caller-supplied `name_cap`-byte buffer.
 *
 * # Safety
 * `out_name` must point to at least `name_cap` writable bytes (NULL
 * skips the name copy). `out_value` must be a writable `uint16_t*`
 * (NULL skips the value copy).
 */
uint8_t lr_srv6_behavior_from_wire(uint16_t wire,
                                   uint16_t *out_value,
                                   char *out_name,
                                   uintptr_t name_cap);

/**
 * Get the 16-bit wire value of a `Behavior`. The behavior is identified
 * by its wire value `wire` — invalid values return 0.
 */
uint16_t lr_srv6_behavior_wire_value(uint16_t wire);

/**
 * True when `wire` is one of the PSP-flavored End.* behaviors (PSP =
 * Penultimate Segment Pop, RFC 8986 §4.16). Returns 0 for unknown
 * values.
 */
uint8_t lr_srv6_behavior_is_psp(uint16_t wire);

/**
 * True when `wire` is one of the USP-flavored End.* behaviors (USP =
 * Ultimate Segment Pop, RFC 8986 §4.16).
 */
uint8_t lr_srv6_behavior_is_usp(uint16_t wire);

/**
 * True when `wire` is one of the USD-flavored End.* behaviors (USD =
 * Ultimate Segment Decap, RFC 8986 §4.16).
 */
uint8_t lr_srv6_behavior_is_usd(uint16_t wire);

/**
 * True when `wire` is a decap behavior (End.D*, RFC 8986 §4.5-§4.13).
 */
uint8_t lr_srv6_behavior_is_decap(uint16_t wire);

/**
 * True when `wire` is a cross-connect behavior (End.X*, RFC 8986 §4.2).
 */
uint8_t lr_srv6_behavior_is_cross_connect(uint16_t wire);

/**
 * True when `wire` is a table-lookup behavior (End.DT*, RFC 8986
 * §4.7-§4.9).
 */
uint8_t lr_srv6_behavior_is_table_lookup(uint16_t wire);

/**
 * Write the behavior's mnemonic name (e.g. `"End"`, `"End.DX6"`) into
 * the caller-supplied buffer. Returns the number of bytes written
 * (excluding the NUL terminator), or 0 if `wire` is unknown or
 * `out_name` is NULL.
 *
 * # Safety
 * `out_name` must point to at least `name_cap` writable bytes.
 */
uintptr_t lr_srv6_behavior_name(uint16_t wire, char *out_name, uintptr_t name_cap);

/**
 * Construct a `Sid` from 16 raw octets.
 *
 * # Safety
 * `octets` must point to 16 readable bytes.
 */
struct OpaqueSrv6Sid *lr_srv6_sid_new(const uint8_t *octets);

/**
 * Write the SID's 16 octets to `out_octets`.
 *
 * # Safety
 * `sid` must be a valid handle. `out_octets` must point to 16 writable
 * bytes.
 */
int32_t lr_srv6_sid_octets(lr_srv6_sid_t sid, uint8_t *out_octets);

/**
 * 1 when `sid` is the unspecified SID (`::`), 0 otherwise.
 *
 * # Safety
 * `sid` must be a valid handle.
 */
uint8_t lr_srv6_sid_is_unspecified(lr_srv6_sid_t sid);

/**
 * Drop a boxed `Sid`. Safe to call with NULL.
 *
 * # Safety
 * `sid` must have been produced by [`lr_srv6_sid_new`] and must not
 * be used after this call.
 */
void lr_srv6_sid_free(lr_srv6_sid_t sid);

/**
 * Construct a `Locator` from a 16-byte address and a block-bit width.
 * Returns NULL when `block_bits > 128` or `addr` is NULL.
 *
 * # Safety
 * `addr` must point to 16 readable bytes.
 */
lr_srv6_locator_t lr_srv6_locator_new(const uint8_t *addr, uint8_t block_bits);

/**
 * Drop a boxed `Locator`. Safe to call with NULL.
 *
 * # Safety
 * `loc` must have been produced by [`lr_srv6_locator_new`] and must
 * not be used after this call.
 */
void lr_srv6_locator_free(lr_srv6_locator_t loc);

/**
 * Write the locator's 16-byte address to `out_addr`.
 *
 * # Safety
 * `loc` must be a valid handle. `out_addr` must point to 16 writable
 * bytes.
 */
int32_t lr_srv6_locator_addr(lr_srv6_locator_t loc, uint8_t *out_addr);

/**
 * Read the locator's block-bit width.
 *
 * # Safety
 * `loc` must be a valid handle.
 */
uint8_t lr_srv6_locator_block_bits(lr_srv6_locator_t loc);

/**
 * 1 when `sid` falls inside this locator, 0 otherwise. Returns 0 on a
 * NULL handle.
 *
 * # Safety
 * `loc` and `sid` must be valid handles.
 */
uint8_t lr_srv6_locator_contains_sid(lr_srv6_locator_t loc, lr_srv6_sid_t sid);

/**
 * Build a SID by combining this locator's prefix with a 16-byte tail.
 * Returns NULL on a NULL locator or when the tail address is NULL.
 *
 * # Safety
 * `loc` must be a valid handle. `tail` must point to 16 readable bytes.
 */
lr_srv6_sid_t lr_srv6_locator_sid_with_tail(lr_srv6_locator_t loc, const uint8_t *tail);

/**
 * Construct a locator from a SID and a block-bits count (RFC 8754
 * §3.1). Returns NULL on a NULL `sid` handle or when the SID cannot
 * host a locator of the requested width.
 *
 * # Safety
 * `sid` must be a valid handle.
 */
lr_srv6_locator_t lr_srv6_locator_from_sid(lr_srv6_sid_t sid, uint8_t block_bits);

/**
 * The locator's block byte width (block_bits / 8, rounded up).
 * Returns 0 on a NULL handle.
 *
 * # Safety
 * `loc` must be a valid handle.
 */
uintptr_t lr_srv6_locator_block_bytes(lr_srv6_locator_t loc);

/**
 * Build a SID by combining this locator with a 32-bit function
 * index (RFC 8754 §3.2). The index is placed in the function-bits
 * portion of the SID. Returns NULL when the locator cannot host
 * the index (e.g. the locator's block width leaves no room).
 *
 * # Safety
 * `loc` must be a valid handle.
 */
lr_srv6_sid_t lr_srv6_locator_sid_with_index(lr_srv6_locator_t loc, uint32_t function_index);

/**
 * Compute the (offset, length) byte range of the locator inside a
 * SID, given the locator's block-bits count. Writes the offset and
 * length to `*out_offset` and `*out_len`. Returns 1 on success, 0
 * when the locator block-bits value is invalid for this SID.
 *
 * # Safety
 * `sid` must be a valid handle. `out_offset` and `out_len` must
 * point to writable `uintptr_t`.
 */
uint8_t lr_srv6_sid_locator_slice(lr_srv6_sid_t sid,
                                  uint8_t locator_block_bits,
                                  uintptr_t *out_offset,
                                  uintptr_t *out_len);

/**
 * Build a SID by concatenating a locator byte string and a tail byte
 * string, given the locator's block-bits count. The locator and tail
 * lengths are passed explicitly so the C ABI mirrors the Rust
 * `Sid::from_locator_tail(locator: &[u8], tail: &[u8], block_bits)`
 * shape — the caller does not have to remember a "16-byte buffer"
 * contract. Returns NULL when the widths are inconsistent
 * (`locator.len() != block_bits / 8` or `tail.len() + loc_bytes != 16`).
 *
 * # Safety
 * `locator` must point to `locator_len` readable bytes; `tail` must
 * point to `tail_len` readable bytes.
 */
lr_srv6_sid_t lr_srv6_sid_from_locator_tail(const uint8_t *locator,
                                            uintptr_t locator_len,
                                            const uint8_t *tail,
                                            uintptr_t tail_len,
                                            uint8_t locator_block_bits);

/**
 * True when the SID lives inside the locator byte string of width
 * `locator_block_bits`. The `locator` pointer must point to
 * `locator_len` readable bytes; `locator_len` MUST equal
 * `block_bits / 8` (the Rust API enforces this — a mismatched length
 * returns `false` rather than reading past the buffer).
 *
 * # Safety
 * `sid` must be a valid handle. `locator` must point to
 * `locator_len` readable bytes.
 */
uint8_t lr_srv6_sid_is_inside_locator(lr_srv6_sid_t sid,
                                      const uint8_t *locator,
                                      uintptr_t locator_len,
                                      uint8_t locator_block_bits);

/**
 * Read the SID's byte slice as a `*const uint8_t` pointer (16 bytes
 * readable). The pointer is valid as long as the SID handle is alive.
 * Returns NULL on a NULL sid handle.
 *
 * # Safety
 * `sid` must be a valid handle. The caller must not free the returned
 * pointer (it borrows from the SID handle).
 */
const uint8_t *lr_srv6_sid_as_ptr(lr_srv6_sid_t sid);

/**
 * `lr_srv6_srh_err_code` — return the discriminant of the most recent
 * `SrhError` produced by `lr_srv6_encode_srh` / `lr_srv6_decode_srh`.
 * Mirrors the substring-match logic of `lr_srv6_srh_last_err_code`,
 * kept as a separate entry point so a future typed-error-pointer
 * surface can call into `srh_err_code` directly without going through
 * the thread-local string. Returns `LR_SRV6_SRH_ERR_UNKNOWN` (-1)
 * when no SRH error is recorded.
 */
int32_t lr_srv6_srh_err_code(void);

/**
 * `lr_srv6_srh_last_err_code` — return the discriminant of the last
 * SRH encode/decode error stored in the thread-local last-error
 * string. Returns `LR_SRV6_SRH_ERR_UNKNOWN` (-1) when no SRH error
 * is recorded (e.g. the last FFI call succeeded or stored a non-SRH
 * error).
 *
 * This is a peek-only helper: it does not clear the last-error
 * string. Callers that need the human-readable message should still
 * call `lr_last_error`.
 */
int32_t lr_srv6_srh_last_err_code(void);

/**
 * Construct an SRH from a flat array of SID bytes. Each SID is 16
 * bytes; `data` must be `count * 16` bytes long. `segments_left`
 * defaults to `count - 1` (RFC 8754 §4.2 — the sender's view).
 *
 * Returns NULL on a panic or on an SRH construction error (empty
 * segment list, too many segments, segments_left out of range).
 *
 * # Safety
 * `data` must point to `count * 16` readable bytes.
 */
lr_srv6_srh_t lr_srv6_srh_new(const uint8_t *data, uintptr_t count);

/**
 * Construct an SRH with an explicit `segments_left` (RFC 8754 §4.2).
 * `segments_left_present = 0` defaults to `count - 1`.
 *
 * # Safety
 * See [`lr_srv6_srh_new`].
 */
lr_srv6_srh_t lr_srv6_srh_new_with_segments_left(const uint8_t *data,
                                                 uintptr_t count,
                                                 uint8_t segments_left,
                                                 uint8_t segments_left_present);

/**
 * Set the Next Header field (RFC 8200 §2). Builder-style — returns
 * 0 on success. The handle is modified in place.
 *
 * # Safety
 * `srh` must be a valid handle.
 */
int32_t lr_srv6_srh_set_next_header(lr_srv6_srh_t srh, uint8_t next_header);

/**
 * Set the SRH flags byte (RFC 8754 §2.1 — currently only OAM/HMAC
 * bits are defined).
 *
 * # Safety
 * `srh` must be a valid handle.
 */
int32_t lr_srv6_srh_set_flags(lr_srv6_srh_t srh, uint8_t flags);

/**
 * Set the SRH tag field (RFC 8754 §2.4 — opaque to the data plane).
 *
 * # Safety
 * `srh` must be a valid handle.
 */
int32_t lr_srv6_srh_set_tag(lr_srv6_srh_t srh, uint16_t tag);

/**
 * Set the SRH TLVs (RFC 8754 §2.5 — variable-length TLV bytes
 * appended after the segment list).
 *
 * # Safety
 * `srh` must be a valid handle. `tlvs` must point to `tlvs_len`
 * readable bytes (NULL with `tlvs_len == 0` clears the TLVs).
 */
int32_t lr_srv6_srh_set_tlvs(lr_srv6_srh_t srh, const uint8_t *tlvs, uintptr_t tlvs_len);

/**
 * Read the Next Header field. Returns 0 on a NULL handle.
 */
uint8_t lr_srv6_srh_next_header(lr_srv6_srh_t srh);

/**
 * Read the segments_left field (RFC 8754 §2.3 — index of the
 * current destination in the segment list). Returns 0 on a NULL
 * handle.
 */
uint8_t lr_srv6_srh_segments_left(lr_srv6_srh_t srh);

/**
 * Read the last_entry field (RFC 8754 §2.3 — index of the last
 * segment in the list). Returns 0 on a NULL handle.
 */
uint8_t lr_srv6_srh_last_entry(lr_srv6_srh_t srh);

/**
 * Read the flags byte. Returns 0 on a NULL handle.
 */
uint8_t lr_srv6_srh_flags(lr_srv6_srh_t srh);

/**
 * Read the tag field. Returns 0 on a NULL handle.
 */
uint16_t lr_srv6_srh_tag(lr_srv6_srh_t srh);

/**
 * Read the segment count. Returns 0 on a NULL handle.
 */
uintptr_t lr_srv6_srh_segment_count(lr_srv6_srh_t srh);

/**
 * Read one segment by index into `*out` (16 bytes). Returns 0 on
 * success, `LR_ERR_NULL` (-1) on a NULL handle or NULL `out`,
 * `LR_ERR_INVALID_HANDLE` (-2) when the index is out of range.
 *
 * # Safety
 * `srh` must be a valid handle. `out` must point to 16 writable bytes.
 */
int32_t lr_srv6_srh_segment_at(lr_srv6_srh_t srh, uintptr_t index, uint8_t *out);

/**
 * Read the TLV bytes into a freshly-allocated `lr_bytes_t`. The
 * caller owns the bytes and must free them via `lr_bytes_free`.
 *
 * # Safety
 * `srh` must be a valid handle. `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_srv6_srh_tlvs(lr_srv6_srh_t srh, struct lr_bytes_t *out);

/**
 * Read the first segment (the destination address at the sender per
 * RFC 8754 §4.2) into `*out` (16 bytes). Returns 0 on success,
 * `LR_ERR_NULL` on a NULL handle or NULL `out`, `LR_ERR_INVALID_HANDLE`
 * when the SRH has no segments.
 *
 * # Safety
 * `srh` must be a valid handle. `out` must point to 16 writable bytes.
 */
int32_t lr_srv6_srh_first_segment(lr_srv6_srh_t srh, uint8_t *out);

/**
 * Encode the SRH into a freshly-allocated `lr_bytes_t` (RFC 8754
 * §2 wire form — 8-octet fixed header + segment list + TLVs). The
 * caller owns the bytes and must free them via `lr_bytes_free`.
 *
 * # Safety
 * `srh` must be a valid handle. `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_srv6_srh_encode(lr_srv6_srh_t srh, struct lr_bytes_t *out);

/**
 * Drop an SRH handle. Safe to call with NULL.
 *
 * # Safety
 * `srh` must have been produced by `lr_srv6_srh_new` and not already
 * freed.
 */
void lr_srv6_srh_free(lr_srv6_srh_t srh);

/**
 * Parse a NUL-terminated IPv6 address string (RFC 4291 §2.2 textual
 * form, the same input `Sid::from_str` accepts) into a `Sid` (16-byte
 * octet array).
 *
 * # Returns
 * - `0` on success — the 16 raw bytes are written to `out`.
 * - `LR_ERR_NULL` (-1) on a NULL `s` or `out`.
 * - `LR_ERR_BAD_UTF8` (-3) when `s` is not valid UTF-8.
 * - `LR_ERR_PANIC` (-4) on a panic inside the parser.
 * - **Positive** values are `SidParseError` discriminant codes
 *   (mirrors `lr_srv6::SidParseError`):
 *   - `1` = `Empty`
 *   - `2` = `DoubleDoubleColon`
 *   - `3` = `BadHextet`
 *   - `4` = `WrongLength`
 *
 * Use [`lr_srv6_sid_parse_error_name`] to render the discriminant as
 * the variant name. Mirrors `Sid::from_str` in `lr_srv6::sid` — the
 * discriminants are stable across the C ABI surface.
 *
 * # Safety
 * `s` must point to a NUL-terminated UTF-8 string. `out` must point
 * to 16 writable bytes.
 */
int32_t lr_srv6_sid_from_str(const char *s, uint8_t *out);

/**
 * Format a `Sid` (16 raw bytes) as an IPv6 address string. Returns
 * a pointer to a thread-local NUL-terminated buffer (valid until
 * the next call to `lr_srv6_sid_to_str` / `lr_srv6_locator_to_str`
 * on this thread). Returns NULL on a NULL `sid` pointer.
 *
 * # Safety
 * `sid` must point to 16 readable bytes.
 */
const char *lr_srv6_sid_to_str(const uint8_t *sid);

/**
 * Parse a NUL-terminated `<addr>/<block_bits>` string (RFC 4291 +
 * RFC 8754 §3.1 textual form) into a `Locator`. Writes the 16-byte
 * address to `out_addr` and the block_bits to `*out_block_bits`.
 *
 * # Returns
 * - `0` on success.
 * - `LR_ERR_NULL` (-1) on a NULL pointer.
 * - `LR_ERR_BAD_UTF8` (-3) when `s` is not valid UTF-8.
 * - `LR_ERR_PANIC` (-4) on a panic inside the parser.
 * - **Positive** values are `LocatorParseError` discriminant codes
 *   (mirrors `lr_srv6::LocatorParseError`):
 *   - `1` = `MissingPrefixLen`
 *   - `2` = `BadAddr` (the IPv6 portion was malformed; the
 *     underlying `SidParseError` is recorded in the last-error
 *     string for diagnostics)
 *   - `3` = `BadPrefixLen`
 *
 * Use [`lr_srv6_locator_parse_error_name`] to render the discriminant
 * as the variant name. Mirrors `Locator::from_str` in
 * `lr_srv6::locator` — the discriminants are stable across the C ABI
 * surface.
 *
 * # Safety
 * `s` must point to a NUL-terminated UTF-8 string. `out_addr` must
 * point to 16 writable bytes and `out_block_bits` to a writable
 * `uint8_t`.
 */
int32_t lr_srv6_locator_from_str(const char *s, uint8_t *out_addr, uint8_t *out_block_bits);

/**
 * Format a `Locator` (16 raw address bytes + block_bits) as the
 * canonical RFC 5952 §4 + RFC 8754 §3.1 `<addr>/<bits>` form. The
 * address portion is rendered through `Sid`'s `Display` impl so the
 * output matches `Locator::Display` in `lr_srv6::locator` exactly —
 * runs of >= 2 zero hextets are compressed to `::`, leading zeros
 * inside each hextet are dropped.
 *
 * Returns a thread-local pointer (valid until the next call to
 * `lr_srv6_sid_to_str` / `lr_srv6_locator_to_str` on this thread).
 *
 * # Safety
 * `addr` must point to 16 readable bytes.
 */
const char *lr_srv6_locator_to_str(const uint8_t *addr, uint8_t block_bits);

/**
 * Decode an ORIGIN attribute (RFC 4271 §5.1.2). `data` is the
 * attribute value (1 byte: 0=IGP, 1=EGP, 2=INCOMPLETE). Writes the
 * origin kind (0/1/2) to `*out`. Returns 0 on success, `LR_ERR_NULL`
 * on a NULL pointer, `LR_ERR_OTHER` on a decode failure.
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out` must point to a
 * writable `uint8_t`.
 */
int32_t lr_bgp_well_known_origin_decode(const uint8_t *data, uintptr_t len, uint8_t *out);

/**
 * Encode an ORIGIN attribute. `kind` is 0 (IGP), 1 (EGP) or 2
 * (INCOMPLETE). Writes 1 byte to `*out`.
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_origin_encode(uint8_t kind, struct lr_bytes_t *out);

/**
 * Decode a NEXT_HOP attribute (RFC 4271 §5.1.3). `data` is the
 * attribute value: 4 bytes (IPv4) or 16 bytes (IPv6 for IPv4 NLRI
 * under RFC 5549). Writes 1 to `*out_is_ipv6` when the next-hop is
 * IPv6 (or IPv4-over-IPv6), 0 when it is IPv4. The address bytes
 * are written to `*out_addr` (4 bytes for v4, 16 for v6).
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out_is_ipv6` must
 * point to a writable `uint8_t`. `out_addr` must point to 16
 * writable bytes (the function always writes 16, with the trailing
 * 12 bytes zeroed for a v4 next-hop).
 */
int32_t lr_bgp_well_known_next_hop_decode(const uint8_t *data,
                                          uintptr_t len,
                                          uint8_t *out_is_ipv6,
                                          uint8_t *out_addr);

/**
 * Encode a NEXT_HOP attribute. `is_ipv6 = 0` writes 4 bytes (IPv4),
 * `is_ipv6 = 1` writes 16 bytes (IPv6). `addr` must point to 4 or
 * 16 readable bytes accordingly.
 *
 * # Safety
 * `addr` must point to 4 readable bytes when `is_ipv6 == 0`, or 16
 * readable bytes when `is_ipv6 == 1`. `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_next_hop_encode(uint8_t is_ipv6,
                                          const uint8_t *addr,
                                          struct lr_bytes_t *out);

/**
 * Decode a MULTI_EXIT_DISC attribute (RFC 4271 §5.1.4). `data` is
 * 4 bytes (big-endian u32). Writes the metric to `*out`.
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out` must point to a
 * writable `uint32_t`.
 */
int32_t lr_bgp_well_known_med_decode(const uint8_t *data, uintptr_t len, uint32_t *out);

/**
 * Encode a MULTI_EXIT_DISC attribute. Writes 4 bytes (big-endian u32).
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_med_encode(uint32_t value, struct lr_bytes_t *out);

/**
 * Decode a LOCAL_PREF attribute (RFC 4271 §5.1.5). `data` is 4 bytes.
 *
 * # Safety
 * See [`lr_bgp_well_known_med_decode`].
 */
int32_t lr_bgp_well_known_local_pref_decode(const uint8_t *data, uintptr_t len, uint32_t *out);

/**
 * Encode a LOCAL_PREF attribute. Writes 4 bytes.
 *
 * # Safety
 * See [`lr_bgp_well_known_med_encode`].
 */
int32_t lr_bgp_well_known_local_pref_encode(uint32_t value, struct lr_bytes_t *out);

/**
 * Decode an AGGREGATOR attribute (RFC 4271 §5.1.7 / RFC 6793). The
 * `data` argument is 6 bytes (2-octet AS + 4-octet speaker) or 8
 * bytes (4-octet AS + 4-octet speaker). Writes the ASN to `*out_asn`
 * and the 4-byte speaker BGP identifier to `out_speaker`.
 *
 * # Safety
 *
 * `data` must point to `len` readable bytes. `out_asn` must point
 * to a writable `uint32_t`. `out_speaker` must point to 4 writable
 * bytes.
 */
int32_t lr_bgp_well_known_aggregator_decode(const uint8_t *data,
                                            uintptr_t len,
                                            uint32_t *out_asn,
                                            uint8_t *out_speaker);

/**
 * Encode an AGGREGATOR attribute in the 4-octet-AS form (RFC 6793).
 * Writes 8 bytes.
 *
 * # Safety
 * `speaker` must point to 4 readable bytes. `out` must point to a
 * writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_aggregator_encode_4(uint32_t asn,
                                              const uint8_t *speaker,
                                              struct lr_bytes_t *out);

/**
 * Decode an ORIGINATOR_ID attribute (RFC 4456 §8). `data` is 4 bytes
 * (BGP Identifier). Writes the identifier to `*out_bgp_id`.
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out_bgp_id` must
 * point to a writable `uint32_t`.
 */
int32_t lr_bgp_well_known_originator_id_decode(const uint8_t *data,
                                               uintptr_t len,
                                               uint32_t *out_bgp_id);

/**
 * Encode an ORIGINATOR_ID attribute. Writes 4 bytes.
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_originator_id_encode(uint32_t bgp_id, struct lr_bytes_t *out);

/**
 * Decode a CLUSTER_LIST attribute (RFC 4456 §8). `data` is a
 * sequence of 4-byte cluster IDs. Writes the cluster IDs as a flat
 * `uint32_t` array into a caller-supplied buffer; writes the count
 * to `*out_count`. If the buffer is too small, writes the required
 * count and returns `LR_ERR_OTHER`.
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out_clusters` must
 * point to `cap` writable `uint32_t` values (NULL is allowed only
 * when `cap == 0`, in which case the function only reports the
 * count). `out_count` must point to a writable `uintptr_t`.
 */
int32_t lr_bgp_well_known_cluster_list_decode(const uint8_t *data,
                                              uintptr_t len,
                                              uint32_t *out_clusters,
                                              uintptr_t cap,
                                              uintptr_t *out_count);

/**
 * Encode a CLUSTER_LIST attribute from a flat `uint32_t` array of
 * cluster IDs. Writes `count * 4` bytes.
 *
 * # Safety
 * `clusters` must point to `count` readable `uint32_t` values (NULL
 * is allowed only when `count == 0`). `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_cluster_list_encode(const uint32_t *clusters,
                                              uintptr_t count,
                                              struct lr_bytes_t *out);

/**
 * Decode an AIGP attribute (RFC 7311). `data` is the TLV form: a
 * single TLV with type 1 (AIGP) and a 64-bit accumulated metric.
 * Writes the metric to `*out_metric`.
 *
 * # Safety
 * `data` must point to `len` readable bytes. `out_metric` must
 * point to a writable `uint64_t`.
 */
int32_t lr_bgp_well_known_aigp_decode(const uint8_t *data, uintptr_t len, uint64_t *out_metric);

/**
 * Encode an AIGP attribute. Writes the TLV form (12 bytes: 2-byte
 * type + 2-byte length + 8-byte metric).
 *
 * # Safety
 * `out` must point to a writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_aigp_encode(uint64_t metric, struct lr_bytes_t *out);

/**
 * Decode a PMSI Tunnel attribute (RFC 6514 §5). `data` is the
 * attribute value: 1 byte flags + 1 byte tunnel type + 1 byte
 * label length (always 3) + 3-byte label + tunnel-id bytes. Writes
 * the flags, tunnel type, label, and tunnel-id length to the
 * out-pointers; the tunnel-id bytes are returned via `out_tunnel_id`
 * as a `lr_bytes_t` (caller frees with `lr_bytes_free`).
 *
 * # Safety
 * `data` must point to `len` readable bytes. The four scalar
 * out-pointers must point to writable memory of the right type.
 * `out_tunnel_id` must point to a writable `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_pmsi_tunnel_decode(const uint8_t *data,
                                             uintptr_t len,
                                             uint8_t *out_flags,
                                             uint8_t *out_tunnel_type,
                                             uint32_t *out_label,
                                             struct lr_bytes_t *out_tunnel_id);

/**
 * Encode a PMSI Tunnel attribute. `label` is a 20-bit MPLS label
 * packed into the low 20 bits of a `uint32_t`. `tunnel_id` is the
 * tunnel-id bytes (NULL only when `tunnel_id_len == 0`).
 *
 * # Safety
 * `tunnel_id` must point to `tunnel_id_len` readable bytes (NULL
 * only when `tunnel_id_len == 0`). `out` must point to a writable
 * `lr_bytes_t`.
 */
int32_t lr_bgp_well_known_pmsi_tunnel_encode(uint8_t flags,
                                             uint8_t tunnel_type,
                                             uint32_t label,
                                             const uint8_t *tunnel_id,
                                             uintptr_t tunnel_id_len,
                                             struct lr_bytes_t *out);

#endif  /* LR_FFI_H */
